local Text_SchoolConfig = readonly({
  SchoolConfig_1_Name = {Text = "Chaos"},
  SchoolConfig_1_SchoolBattleTips_1 = {
    Text = "·Silberner Schlüssereklang: Am Ende der Runde erhält man 250 Punkte Keyflare. Nach der Verwendung eines Schlüsselbefehls erhalten alle Erwecker <BlueQuality:[Arg1]> Punkte Aliemus. Bei der zweiten Freisetzung des Schlüsselbefehls wird stattdessen “Unvergessene Dämmerung“ freigegeben: Wähle 1 freigeschalteten Schlüsselbefehl aus und lasse ihn 2 Mal wirken, wobei jeder freigeschaltete Schlüsselbefehl in dieser Erkundung nur einmal gewählt werden kann und der zu Beginn mitgeführte Schlüsselbefehl nicht gewählt werden kann."
  },
  SchoolConfig_1_SchoolBattleTips_2 = {
    Text = "Urzeitlicher Zufluss: Basis-Keyflare wird auf 2000 erhöht, Team-Schadenamplifikation wird um 50% erhöht, und ANG sowie VERT aller Erwecker werden um 10% erhöht. Wenn das Team ausschließlich aus Chaoswachkörpern besteht, wird der Schadenamplifikations-Bonus dieses Effekts verdoppelt. Zu Kampfbeginn werden 2000 Keyflare erhalten.\n\nVereinte Schlüssel: Die Keyflare-Regenerations-Level aller Erwecker werden auf den Teamdurchschnitt gesetzt und verfallen nicht mehr. Erwecker erhalten keine Keyflare mehr durch verbrauchte Arithmetica; stattdessen gewährt die erste von jedem Erwecker pro Runde gespielte Befehlskarte Keyflare in Höhe von (Keyflare-Regeneration dieses Erweckers × 3) + 100.\n\nUnteilbares Reich: Löst nicht mehr die Effekte „Reines Reich“, „Doppelte Reichsbeherrschung“ oder „Doppelte Schadenamplifikation“ anderer Reiche aus.\n\nUrecho: Erwecken-Karten erhalten Vorbereiten 1; die aktuell ausgerüstete Posse wird automatisch entfesselt, wenn sie zum ersten Mal pro Runde gespielt wird.\n\nErinnerungsfragmente: Die Posse wird durch Primordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung ersetzt, und die mitgeführte Posse selbst kann nicht mehr entfesselt werden.\n\n–Primordia: Doppelte Wiederkehr: Entdecke 3 Possen aus denen auf der Hand und wähle 1, um sie zweimal zu entfesseln.\n–Primordia: Triade der Offenbarung: Entdecke 3 Possen-Sets aus denen auf der Hand, wobei jedes Set 3 verschiedene Possen enthält. Wähle ein Set, um jede darin enthaltene Posse einmal der Reihe nach zu entfesseln.\nDie in Primordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung vorkommenden Possen werden aus den acht Arten der Urerinnerung gezogen.\nPrimordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung zählen jeweils nur als Entfesseln von 1 Posse. Wenn ihre Effekte mehrfach ausgelöst würden, ist nur die erste wirksame Posse gültig.\n\nPrimordia: Chaotische Beherrschung: Reichsbeherrschung wird zu Primordia: Chaotische Beherrschung. Jeder Punkt Primordia: Chaotische Beherrschung erhöht die Possen-Stärke um 0,05%. Jeder Punkt Possen-Stärke erhöht festes Gift, festen Gegenangriff, feste STR und Alte Glut um je 2% sowie festen Schild, feste LP-Wiederherstellung, STR ▼, Krit. Rate, Krit. Schaden, Schadenamplifikation, Reichsbeherrschung, Aliemus-Generierung, Embryofusion und Keyflare-Generierung um je 1%."
  },
  SchoolConfig_1_SchoolFeature = {
    Text = "Wenn die Erwachten dieses Bereichs mit Erwachten anderer Bereiche gemischt sind, können sie die entsprechenden Fähigkeiten des jeweiligen Bereichs verstärken. Bei einer vollständigen Chaos-Aufstellung besitzen sie zudem eine mächtigere Kontrolle über den Silberschlüssel."
  },
  SchoolConfig_1_SchoolTips = {
    Text = "Stärkere Silberschlüsselkräfte, die die Eigenschaften eines anderen Reichs bei einer Mischung maximal zur Geltung bringen können."
  },
  SchoolConfig_1_SchoolTipsName = {
    Text = "Universum und seine Phänomene"
  },
  SchoolConfig_1_Tips = {
    Text = "·Silberner Schlüssereklang: Am Ende der Runde erhältst du 250 Punkte s-Energie. Nach der Freisetzung des Schlüsselbefehls erhalten alle Erwecker 5 Punkte Aliemus. Bei der zweiten Freisetzung des Schlüsselbefehls wird stattdessen „Unvergessene Dämmerung \" freigesetzt: Wähle 1 freigeschalteten Schlüsselbefehl, um ihn 2-mal zu aktivieren. Jeder freigeschaltete Schlüsselbefehl kann in dieser Erkundung nur 1-mal gewählt werden, der anfänglich mitgeführte Schlüsselbefehl kann nicht gewählt werden. \n·Omniscent Schöpfung: Wenn der Schutzherr Level 45 erreicht, wird zu Beginn der Erkundung 1 Silberne Schöpfung entdeckt. \n·Chaotische Beherrschung: Für jeden Punkt Reichsbeherrschung im Team erhalten alle Erwecker nach der Freisetzung des Schlüsselbefehls zusätzlich 0, 05 Punkte Aliemus. \n·Todesverachtung: In jedem Team, wenn ein Chaoswachkörper vorhanden ist, erhöht sich der Todwiderstand um 100%. \n·Chaotische Symbiose: Wenn mit anderen Bereichen gemischt, sind „Silberner Schlüssereklang\", „Omniscent Schöpfung \" und „Chaotische Beherrschung\" nicht mehr aktiv und lösen stets die reinsten Talenteffekte anderer Bereiche aus, wobei je nach Bereich unterschiedliche symbiotische Effekte erzielt werden. \n·Aequor-Symbiose: Für jeden Chaoswachkörper im Team wird der Basis-Tentakelschaden um 1% der maximalen Lebenspunkte erhöht. Nach der Freisetzung der Verherrlichung durch Chaoswachkörper wird am Ende der Runde zusätzlich 1 Tentakel aktiviert, um den Feind anzugreifen, und alle Tiefseewachkörper erhalten 10 Punkte Aliemus. \n·Fleisch-Symbiose: Nach der Verherrlichung eines Chaoswachkörpers erhöht sich die Embryofusion um 35. \n·Hyperdimensionale Symbiose: Zu Beginn des Kampfes erhöht sich für jeden Chaoswachkörper im Team dauerhaft die Kraft um 1% der maximalen Lebenspunkte und reduziert die eigene maximale Lebenskraft aller Gegner um 0, 5%, während der kritische Schaden aller hyperdimensionalen Erwachungskörper um 10% erhöht wird."
  },
  SchoolConfig_2_Name = {Text = "Fleisch"},
  SchoolConfig_2_SchoolBattleTips_1 = {
    Text = "·Embryofusion: Zu Beginn der Runde erhältst du Embryofusion +<BlueQuality:[Arg1]>.\n·Blutroter Ofen: Zu Beginn der Runde sammle <BlueQuality:[Arg9]> Punkte Blutroter Ofen. Nach dem Kampf sammle <BlueQuality:[Arg2]> Punkte Blutroter Ofen, wenn das aktuelle Reich „Perfektes Fleisch \" ist, wird die Menge verdoppelt, maximal <BlueQuality:[Arg3]> Punkte. Am Ende des Kampfes, für jede verbleibende „Embryo\" in der Hand, sammle zusätzlich <BlueQuality:[Arg2]> Punkte Blutroter Ofen.\n·Embryo verschlingen: Die Verherrlichung des Fleisch-Erwachungskörpers verbraucht „Embryo \" und löst den Verschlingen-Effekt aus. Nach dem ersten Auslösen von „Verschlingen\" in jedem Team pro Runde, erhältst du einen Schild von <BlueQuality:[Arg4] %> der maximalen Lebenspunkte(<BlueQuality:[Arg5]>) und temporäre Stärke von <BlueQuality:[Arg6] %> der maximalen Lebenspunkte(<BlueQuality:[Arg7]>)."
  },
  SchoolConfig_2_SchoolBattleTips_2 = {
    Text = "·Embryofusion: Zu Beginn der Runde erhöht sich die Embryofusion um <BlueQuality:[Arg1]>.\n·Embryonen züchten: Wenn ein Erwecker zum ersten Mal pro Runde „Zuchtembryo \" verbraucht, erhält er <BlueQuality:[Arg4]> Schichten „Ausbreitungsfiesta\": Für jede Schicht erhöht sich der endgültige Effekt der nächsten Verherrlichung dieses Erweckers in dieser Runde – Schaden, fester Schild, feste LP-Heilung, feste Stärke, STR▼, Tentakelschaden erhöht, festes Gift und fester Konter – um 1%.\n·Blutroter Ofen: Zu Beginn der Runde werden <BlueQuality:[Arg2]> Punkte Blutroter Ofen angesammelt, maximal <BlueQuality:[Arg3]> Punkte. 3 Runden Abklingzeit.\n·Scharlachrote Erosion: Nach der Verwendung des Blutroten Ofens wird allen Feinden eine Korrosion in Höhe von 1% der maximalen LP des Ziels zugefügt. Je mehr Blutroter Ofen verbraucht wird, desto stärker ist der Korrosionseffekt, maximal um 100% erhöht. Gegen „Leere Hülle \"-Feinde wird der 5-fache Korrosionseffekt verursacht.\n·Nach Beginn der Erkundung erhöhen sich die maximalen LP um 10%, und die Schadenamplifikation des Teams erhöht sich um +50%. Zu Beginn der Runde erhalten alle Erwecker <BlueQuality:[Arg5]> Schichten „Ausbreitungsfiesta\".\n·Blut und Fleisch Beherrschung: Für jeden Punkt Reichsbeherrschung des Teams erhöht sich die durch „Zuchtfleisch \" erhaltene „Ausbreitungsfiesta\" um 0, 05%.\n·Perfektes Fleisch: Wenn das Team nur aus Fleisch- oder Chaoswachkörpern besteht, verdoppeln sich die Effekte der Blut und Fleisch Beherrschung und der vom Reich bereitgestellten Schadenamplifikation."
  },
  SchoolConfig_2_SchoolFeature = {
    Text = "Der Erwecker in diesem Reich muss auswählen, wie er mit dem Embryo ansammeln und nutzen möchte; er kann aktiv verwendet werden, um flexibel Raserei bereitzustellen oder verschlungen werden, um die Wirkung seiner Raserei zu verstärken"
  },
  SchoolConfig_2_SchoolTips = {
    Text = "Einzigartige Embryos und Schmieden, die darin spezialisiert sind, gegen den Strom zu kämpfen und Risiken in Gewinne umzuwandeln."
